import json
import os


def _load_json(path):
    """Load a JSON file, wrapping decode errors so the message names the file."""
    try:
        with open(path) as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        # Re-raise as JSONDecodeError but include the offending filename.
        raise json.JSONDecodeError(
            f"{path}: invalid JSON ({e.msg})", e.doc, e.pos
        ) from None


def load_config(root):
    # merge root/config.json with every root/conf.d/*.json in sorted filename order;
    # later wins per top-level key
    merged = {}
    base = os.path.join(root, "config.json")
    if os.path.isfile(base):
        merged.update(_load_json(base))
    dropin_dir = os.path.join(root, "conf.d")
    if os.path.isdir(dropin_dir):
        for name in sorted(os.listdir(dropin_dir)):
            path = os.path.join(dropin_dir, name)
            # isfile guard: skip subdirectories (and anything non-regular)
            if name.endswith(".json") and os.path.isfile(path):
                merged.update(_load_json(path))
    return merged

