import json

import pytest

from confloader import load_config


def make_tree(tmp_path, spec):
    """Create files/dirs under tmp_path from {relative/path: content}.

    Non-string values are dumped as JSON; strings are written verbatim
    (append .json content as a string to write intentionally-invalid JSON).
    Intermediate directories are created automatically.
    """
    for rel, content in spec.items():
        path = tmp_path / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        data = content if isinstance(content, str) else json.dumps(content)
        path.write_text(data)
    return tmp_path


def test_missing_root_returns_empty(tmp_path):
    # no config.json, no conf.d -- nothing exists at all
    assert load_config(tmp_path / "does-not-exist") == {}


def test_base_only(tmp_path):
    make_tree(tmp_path, {"config.json": {"a": 1, "b": 2}})
    assert load_config(tmp_path) == {"a": 1, "b": 2}


def test_dropin_overrides_base_per_key(tmp_path):
    make_tree(tmp_path, {
        "config.json": {"a": 1, "b": 2},
        "conf.d/50-x.json": {"b": 99},
    })
    assert load_config(tmp_path) == {"a": 1, "b": 99}


def test_dropins_apply_in_sorted_order(tmp_path):
    make_tree(tmp_path, {
        "config.json": {"key": "base"},
        "conf.d/20-b.json": {"key": "twenty"},
        "conf.d/10-a.json": {"key": "ten"},
    })
    # sorted: 10-a.json first, then 20-b.json -> later wins
    assert load_config(tmp_path) == {"key": "twenty"}


def test_non_json_files_ignored(tmp_path):
    make_tree(tmp_path, {
        "config.json": {"a": 1},
        "conf.d/readme.txt": '{"a": 999}',
        "conf.d/notes.md": "# hello",
        "conf.d/data.bak": "garbage",
    })
    assert load_config(tmp_path) == {"a": 1}


def test_subdirectory_inside_conf_d_ignored(tmp_path):
    make_tree(tmp_path, {
        "config.json": {"a": 1},
        # a directory named like a drop-in must not crash or be read
        "conf.d/subdir.json/nested.json": {"a": 2},
        "conf.d/plain.json": {"b": 3},
    })
    assert load_config(tmp_path) == {"a": 1, "b": 3}


def test_invalid_json_in_dropin_names_file(tmp_path):
    make_tree(tmp_path, {
        "config.json": {"a": 1},
        "conf.d/10-broken.json": "{not valid json",
    })
    with pytest.raises(json.JSONDecodeError) as excinfo:
        load_config(tmp_path)
    # chosen behavior: error message includes the offending filename
    assert "10-broken.json" in str(excinfo.value)


def test_invalid_json_in_base_names_file(tmp_path):
    make_tree(tmp_path, {"config.json": "{"})
    with pytest.raises(json.JSONDecodeError) as excinfo:
        load_config(tmp_path)
    assert "config.json" in str(excinfo.value)

